package com.arjun.signagekioskautousb;import android.content.*;import android.os.Build;public class BootReceiver extends BroadcastReceiver{@Override public void onReceive(Context c,Intent i){try{Intent s=new Intent(c,StartupService.class);if(Build.VERSION.SDK_INT>=26)c.startForegroundService(s);else c.startService(s);}catch(Exception ignored){}try{Intent a=new Intent(c,MainActivity.class);a.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);c.startActivity(a);}catch(Exception ignored){}}}